<?php
/** @var array{css:?string,js:?string} $assets */
/** @var array<int,array<string,string>> $navigation */
/** @var array<string,mixed> $report */
$money = static fn (float $value): string => ($value < 0 ? '−' : '') . '$' . number_format(abs($value), 2);
$date = static fn (?string $value): string => $value === null ? '—' : (new DateTimeImmutable($value))->format('M j, Y');
$query = static function (string $sort, string $defaultDirection = 'desc') use ($report): string {
    $direction = $report['sort'] === $sort ? ($report['direction'] === 'desc' ? 'asc' : 'desc') : $defaultDirection;

    return '?' . http_build_query(['sort' => $sort, 'direction' => $direction]);
};
?>
