umeric" data-label="YTD Earnings"><?= esc($money((float) $row['ytd_earnings'])) ?></td><td class="numeric result-value" data-label="Lifetime Earnings"><?= esc($money((float) $row['lifetime_earnings'])) ?></td></tr><?php endforeach; ?></tbody><tfoot><tr><th scope="row" data-label="Vehicle">Fleet total</th><td data-label="In Service Date">—</td><td class="numeric" data-label="MTD Earnings"><?= esc($money((float) $report['totals']['mtd_earnings'])) ?></td><td class="numeric" data-label="YTD Earnings"><?= esc($money((float) $report['totals']['ytd_earnings'])) ?></td><td class="numeric result-value" data-label="Lifetime Earnings"><?= esc($money((float) $report['totals']['lifetime_earnings'])) ?></td></tr></tfoot></table></div><?php if ($report['has_unallocated']): ?><p class="reconciliation-note">Unallocated / Unmatched preserves valid company revenue associated with a vehicle outside the current report roster so displayed rows reconcile to company totals.</p><?php endif; ?></section>
